/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.search = async function () {
    /* sdd-asis-lifecycle:begin fn_search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const indObj = (document.indForm || { elements: [] });
    $c.util.getComponent("dma_searchReq").set("action", "/discls/disclosureCommon.do");
    $c.util.getComponent('dma_searchReq').set('method', "searchCommonPop");
    $c.util.getComponent('dma_searchReq').set('searchYn', "Y");
    await scwin.tx_fn_search();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkValues
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkValues = async function () {
    /* sdd-asis-lifecycle:begin checkValues — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const indObj = (document.indForm || { elements: [] });
    if ($c.util.getComponent('ipt_searchWord').getValue().length == 0) {
        await $c.win.alert('검색할 업종코드 or 업종명을 입력하십시오.');
        $c.util.getComponent("ipt_searchWord").focus();
        return;
    }
    await scwin.search();
    /* sdd-asis-lifecycle:end */
};
